    if a.arm=='A3': net=nn.ModuleDict({'gs':gs,'sig':SigLIP()}).to(dev)
    else: net=nn.ModuleDict({'gs':gs,'P2':mlp(1024,a.dim),'sig':SigLIP()}).to(dev)
    scale=d.gs_scale(); t=Trainer(a,'gs_encoder',net)
