        with torch.no_grad(): x=d.x(rows,dev)
        if a.arm=='A3':
            with torch.no_grad(): zl=spaces.lf(x)
            return F.mse_loss(zg,zl)+a.w_sig*net['sig'](zg,zl)
        zl=F.normalize(net['P2'](x),dim=-1)
